pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 value, uint256 warpTime, uint256 rollNum) public {
        value = bound(value, 10 ether, 10 ether);
        vm.warp(bound(warpTime, 1, type(uint64).max));
        vm.roll(bound(rollNum, 0, type(uint256).max - 1));

        address sender = makeAddr("sender");
        vm.deal(sender, 10 ether);
        vm.prank(sender);
        (bool ok, ) = address(c).call{value: value}("");
        require(ok, "call must succeed");

        assertTrue(c.pastBlockTime() == block.timestamp + 1);
    }
}
